export const routes=[{path:'/orgs/:orgId/invitations',component:Invitations},{path:'/orgs/:orgId/outbox',component:Outbox},{path:'/invitations/accept',component:AcceptInvitation},{path:'/account/security',component:AccountSecurity},{path:'/account/outbox',component:Outbox},{path:'/reset',component:ResetPassword},{path:'/orgs',component:Organizations},{path:'/orgs/:orgId/members',component:Members},{path:'/orgs/:orgId/teams',component:Teams},{path:'/teams/:teamId',component:TeamDetail}];
export const navigation=[{path:'/orgs',label:'Organizations'},{path:'/account/security',label:'Account security'}];
